/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { SnippetAsset } from 'app/features/template/snippet-asset/model/snippet-asset.model';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { SnippetAssetRepository } from 'app/features/template/snippet-asset/repository/snippet-asset-repository.service';
import { Component, inject } from '@angular/core';

/** Edición masiva de snippet asset: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'snippet-asset-view-bulk-edit-action', standalone: false, template: '' })
export class SnippetAssetViewBulkEditActionComponent extends BaseBulkEditAction<SnippetAsset> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'template/snippet-asset';
  protected readonly repository = inject(SnippetAssetRepository);

  protected override keyOf(item: SnippetAsset): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<SnippetAsset>[] {
    return [
      { name: 'code', label: this.text('fieldCode'), type: 'text' },
      { name: 'type', label: this.text('fieldType'), type: 'text' },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<SnippetAsset> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
